/* @autogenerated */
package net.civeira.phylax.feature.observe.store;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TraceLevelsUnitTest {

  private static final long HOUR = 3_600_000L;
  private static final RetentionPolicy POLICY = new RetentionPolicy(14, 7, 0, 15, 400)
      .withLevels(new RetentionPolicy.LevelRetention(2, 12, 24, 168));

  @TempDir
  Path root;

  private static ObsLog log(final long ts, final String trace, final String level,
      final String msg) {
    return new ObsLog(ts, "api", level, "test", msg, trace, null, null, null, null, null);
  }

  private static ObsSpan span(final long ts, final String trace, final String status) {
    return new ObsSpan(ts, "api", trace, trace + "-s", null, "GET /x", "SERVER", 5, status, null,
        null, null);
  }

  private static TelemetryQuery all() {
    return TelemetryQuery.builder().from(0).to(Long.MAX_VALUE / 2).minLevel(Optional.empty())
        .text(Optional.empty()).limit(10_000).build();
  }

  @Test
  @DisplayName("The level of a row is the highest of its own and its trace; a quiet span is INFO")
  void levels() {
    Assertions.assertEquals(TraceLevels.DEBUG, TraceLevels.of("TRACE"));
    Assertions.assertEquals(TraceLevels.ERROR, TraceLevels.of("FATAL"));
    Assertions.assertEquals(TraceLevels.INFO,
        TraceLevels.effective(TraceLevels.NONE, TraceLevels.NONE));
    Assertions.assertEquals(TraceLevels.ERROR,
        TraceLevels.effective(TraceLevels.DEBUG, TraceLevels.ERROR));
    TraceLevels levels = new TraceLevels();
    Assertions.assertEquals(Map.of(), levels.raise(List.of(log(1, "t1", "DEBUG", "a")), List.of()));
    // Seen before and rising: its stored rows must be marked
    Assertions.assertEquals(Map.of("t1", TraceLevels.ERROR),
        levels.raise(List.of(), List.of(span(2, "t1", "ERROR"))));
    Assertions.assertEquals(Map.of(), levels.raise(List.of(log(3, "t1", "WARN", "b")), List.of()));
    // New at WARN: marked too (its earlier rows may be from before a restart)
    Assertions.assertEquals(Map.of("t2", TraceLevels.WARN),
        levels.raise(List.of(log(4, "t2", "WARN", "c")), List.of()));
    Assertions.assertEquals(TraceLevels.ERROR, levels.level("t1"));
  }

  @Test
  @DisplayName("Each row lives as long as the level of its trace asks, even a DEBUG log of an error")
  void purgeByTraceLevel() throws IOException {
    long now = System.currentTimeMillis();
    // Keep the rows of each case in one day, so the test does not depend on the hour it runs
    long at = now - 3 * HOUR;
    JsonlTelemetryStore store = new JsonlTelemetryStore(root.toString());
    store.appendLogs(List.of(log(at, "debug", "DEBUG", "only debug"),
        log(at, "info", "INFO", "plain"), log(at, "info", "DEBUG", "debug of info"),
        log(at, "failed", "DEBUG", "debug of failed"), log(at, null, "DEBUG", "no trace")));
    store.appendSpans(List.of(span(at, "debug", "OK"), span(at, "info", "OK"),
        span(at, "quiet", "OK"), span(at, "failed", "ERROR")));
    store.purgeLevels(POLICY);
    List<String> logs = store.logs(all()).stream().map(ObsLog::msg).sorted().toList();
    Assertions.assertEquals(List.of("debug of failed", "debug of info", "plain"), logs);
    List<String> traces = store.spans(all()).stream().map(ObsSpan::traceId).sorted().toList();
    Assertions.assertEquals(List.of("failed", "info", "quiet"), traces);
  }

  @Test
  @DisplayName("The rows older than every level go; an error outlives a warning")
  void longestLevel() throws IOException {
    long now = System.currentTimeMillis();
    JsonlTelemetryStore store = new JsonlTelemetryStore(root.toString());
    store.appendLogs(List.of(log(now - 30 * HOUR, "w", "WARN", "old warn"),
        log(now - 30 * HOUR, "e", "ERROR", "old error"),
        log(now - 200 * HOUR, "e2", "ERROR", "too old")));
    store.purgeLevels(POLICY);
    Assertions.assertEquals(List.of("old error"),
        store.logs(all()).stream().map(ObsLog::msg).toList());
    try (var days = Files.list(root)) {
      Assertions.assertTrue(days.count() <= 2, "the days older than every level are removed");
    }
  }
}
